import{templates}from"./templates.min.js";export function renderizar(e,a){e.innerHTML=templates[a]||templates.inicio}export function navegar(e,a){history.pushState({pagina:a},"",`?pagina=${a}`),renderizar(e,a)}export function obterPaginaAtual(){return new URLSearchParams(window.location.search).get("pagina")||"inicio"}